# PTX source for RMSNorm (fp16 inputs/outputs) on SM80
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 features,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .f32 eps
)
{
    // -----------------------------------------------------------------
    // Register declarations
    // -----------------------------------------------------------------
    .reg .pred %p_active, %p0, %p_lt, %p_done;
    .reg .u32 %tid, %bidx, %iidx, %jidx, %features, %dim1, %dim2;
    .reg .u64 %in_ptr, %out_ptr, %offset, %byte_offset;
    .reg .f16 %h_val, %h_orig, %h_out;
    .reg .f32 %orig_f, %sq, %sum_f, %mean_f, %mean_eps_f, %rms_f, %inv_rms_f, %norm_f, %eps_f, %f_features_f;
    .reg .u32 %r0, %r1, %stride, %tmp;
    .reg .u64 %rd_tmp, %rd_tmp2, %rd_tmp3;

    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    ld.param.u64 %in_ptr,    [input_ptr];
    ld.param.u64 %out_ptr,   [output_ptr];
    ld.param.u32 %bidx,      [batch];
    ld.param.u32 %features,  [features];
    ld.param.u32 %dim1,      [dim1];
    ld.param.u32 %dim2,      [dim2];
    ld.param.f32 %eps_f,     [eps];

    // -----------------------------------------------------------------
    // Thread / block indices
    // -----------------------------------------------------------------
    mov.u32 %tid, %tid.x;
    mov.u32 %bidx, %ctaid.x;      // batch index
    mov.u32 %iidx, %ctaid.y;      // dim1 index
    mov.u32 %jidx, %ctaid.z;      // dim2 index

    // -----------------------------------------------------------------
    // Determine if this thread participates (features may be < blockDim.x)
    // -----------------------------------------------------------------
    setp.lt.u32 %p_active, %tid, %features;

    // -----------------------------------------------------------------
    // Compute linear offset for element (b, f, i, j)
    // offset = ((b * features + f) * dim1 + i) * dim2 + j
    // -----------------------------------------------------------------
    mul.lo.u32 %r0, %bidx, %features;          // b * features
    add.u32 %r1, %r0, %tid;                    // b*features + f

    mul.wide.u32 %rd_tmp, %r1, %dim1;          // * dim1  (64‑bit)
    add.u64 %rd_tmp2, %rd_tmp, %iidx;         // + i

    mul.wide.u32 %rd_tmp3, %rd_tmp2, %dim2;   // * dim2
    add.u64 %offset, %rd_tmp3, %jidx;         // + j

    mul.wide.u32 %byte_offset, %offset, 2;    // half‑precision = 2 bytes

    // -----------------------------------------------------------------
    // Load original half‑precision value (only for active threads)
    // -----------------------------------------------------------------
    @%p_active ld.global.f16 %h_val, [%in_ptr + %byte_offset];
    mov.f16 %h_orig, %h_val;                  // keep for later

    // -----------------------------------------------------------------
    // Compute square (float32) for reduction
    // -----------------------------------------------------------------
    @%p_active {
        cvt.f32.f16 %orig_f, %h_val;
        mul.f32 %sq, %orig_f, %orig_f;
    }
    @!%p_active mov.f32 %sq, 0f0;

    // -----------------------------------------------------------------
    // Shared memory buffer (max 128 threads => 128 * 4 bytes)
    // -----------------------------------------------------------------
    .shared .align 4 .b8 shmem[512];   // 128 * 4

    // Store partial sum
    st.shared.f32 [shmem + %tid*4], %sq;

    bar.sync 0;

    // -----------------------------------------------------------------
    // Parallel reduction (binary tree)
    // -----------------------------------------------------------------
    mov.u32 %stride, %blockDim.x;
red_loop:
    shr.u32 %stride, %stride, 1;
    setp.eq.u32 %p_done, %stride, 0;
    @%p_done bra red_done;

    setp.lt.u32 %p_lt, %tid, %stride;
    @%p_lt {
        ld.shared.f32 %f_a, [shmem + %tid*4];
        ld.shared.f32 %f_b, [shmem + (%tid + %stride)*4];
        add.f32 %f_a, %f_a, %f_b;
        st.shared.f32 [shmem + %tid*4], %f_a;
    }
    bar.sync 0;
    bra red_loop;
red_done:

    // -----------------------------------------------------------------
    // Thread 0 computes RMS and writes inverse RMS to shared[0]
    // -----------------------------------------------------------------
    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        ld.shared.f32 %sum_f, [shmem];
        cvt.f32.u32 %f_features_f, %features;
        div.f32 %mean_f, %sum_f, %f_features_f;
        add.f32 %mean_eps_f, %mean_f, %eps_f;
        sqrt.rn.f32 %rms_f, %mean_eps_f;
        rcp.approx.f32 %inv_rms_f, %rms_f;
        st.shared.f32 [shmem], %inv_rms_f;
    }
    bar.sync 0;

    // -----------------------------------------------------------------
    // Broadcast inverse RMS to all threads
    // -----------------------------------------------------------------
    ld.shared.f32 %inv_rms_f, [shmem];

    // -----------------------------------------------------------------
    // Normalize and write output (only active threads)
    // -----------------------------------------------------------------
    @%p_active {
        cvt.f32.f16 %orig_f, %h_orig;
        mul.f32 %norm_f, %orig_f, %inv_rms_f;
        cvt.rn.f16 %h_out, %norm_f;
        st.global.f16 [%out_ptr + %byte_offset], %h_out;
    }

    ret;
}
'''

# -----------------------------------------------------------------
# Python wrapper that loads the PTX and launches the kernel
# -----------------------------------------------------------------
class ModelNew:
    def __init__(self, num_features: int, eps: float = 1e-5):
        self.num_features = num_features
        self.eps = float(eps)
        # Load PTX module using the harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x):
        """
        x: torch.Tensor of shape (B, C, D1, D2), dtype=torch.float16, device='cuda'
        Returns a tensor of same shape and dtype with RMSNorm applied.
        """
        import torch

        assert x.is_cuda and x.dtype == torch.float16
        B, C, D1, D2 = x.shape
        assert C == self.num_features, f'expected {self.num_features} features, got {C}'

        out = torch.empty_like(x)

        # Grid: (batch, dim1, dim2); Block: 128 threads (covers up to 128 features)
        grid = (B, D1, D2)
        block = (128, 1, 1)

        args = [
            x.data_ptr(),
            out.data_ptr(),
            B,
            self.num_features,
            D1,
            D2,
            self.eps,
        ]

        ptx_launch(self.module, "rmsnorm_kernel", grid, block, args)

        return out
